/**
 * The contract `calendar.tsx` (native) and `calendar.web.tsx` (react-day-picker)
 * both implement. Its own module because Metro resolves `./calendar` to
 * `calendar.web.tsx` on web.
 *
 * Single-date selection only. react-day-picker's `mode` is deliberately not in
 * the contract: range and multi selection have no native implementation behind
 * them, and a prop that only works on one platform is a promise half-kept.
 */
export type CalendarProps = {
  selected?: Date | undefined;
  onSelect: (date: Date | undefined) => void;
  /** Month shown on first render; defaults to the selected date's month. */
  defaultMonth?: Date | undefined;
  className?: string | undefined;
};

/**
 * The native calendar: a month grid built from date-fns.
 *
 * Written out rather than pulling in a native calendar library: the whole
 * surface is one month of single-date selection, and a calendar library brings
 * its own theming system that would sit outside the tailwind tokens every other
 * primitive follows.
 */
import {
  addMonths,
  eachDayOfInterval,
  endOfMonth,
  endOfWeek,
  format,
  isSameDay,
  isSameMonth,
  startOfMonth,
  startOfWeek,
} from "date-fns";
import { useState } from "react";
import { Pressable, Text, View } from "react-native";
import type { CalendarProps } from "@/components/ui/calendar-base";
import { ChevronLeft, ChevronRight } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

const WEEKDAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

export function Calendar({ selected, onSelect, defaultMonth, className }: CalendarProps) {
  const [month, setMonth] = useState(() => defaultMonth ?? selected ?? new Date());

  // Padded out to whole weeks so every row has seven cells and the grid does
  // not reflow as the month changes.
  const days = eachDayOfInterval({
    start: startOfWeek(startOfMonth(month)),
    end: endOfWeek(endOfMonth(month)),
  });

  return (
    <View className={cn("p-3", className)}>
      <View className="mb-2 flex-row items-center justify-between">
        <Pressable
          onPress={() => setMonth(addMonths(month, -1))}
          aria-label="Previous month"
          className="p-1"
        >
          <ChevronLeft className="h-4 w-4 text-foreground" />
        </Pressable>
        <Text className="text-sm font-medium text-foreground">{format(month, "MMMM yyyy")}</Text>
        <Pressable
          onPress={() => setMonth(addMonths(month, 1))}
          aria-label="Next month"
          className="p-1"
        >
          <ChevronRight className="h-4 w-4 text-foreground" />
        </Pressable>
      </View>

      <View className="flex-row">
        {WEEKDAYS.map((day) => (
          <Text key={day} className="flex-1 text-center text-xs text-muted-foreground">
            {day}
          </Text>
        ))}
      </View>

      <View className="flex-row flex-wrap">
        {days.map((day) => {
          const isSelected = selected ? isSameDay(day, selected) : false;
          return (
            <Pressable
              key={day.toISOString()}
              onPress={() => onSelect(day)}
              className={cn(
                "h-9 items-center justify-center rounded-md",
                isSelected && "bg-primary",
              )}
              // Seven per row, and `flex-wrap` needs a width it can measure.
              // A `w-[14.2857%]` class would round to the same place; the style
              // keeps the arithmetic visible.
              style={{ width: `${100 / 7}%` }}
            >
              <Text
                className={cn(
                  "text-sm",
                  isSelected
                    ? "text-primary-foreground"
                    : isSameMonth(day, month)
                      ? "text-foreground"
                      : "text-muted-foreground",
                )}
              >
                {format(day, "d")}
              </Text>
            </Pressable>
          );
        })}
      </View>
    </View>
  );
}

/**
 * The web calendar: react-day-picker, using the library's own stylesheet so we
 * do not have to track its evolving `classNames` API across versions.
 * `calendar.tsx` is the native counterpart; `calendar-base.ts` holds the
 * contract they share.
 */
import { DayPicker } from "react-day-picker";
import type { CalendarProps } from "@/components/ui/calendar-base";
import { cn } from "@/lib/utils";
import "react-day-picker/style.css";

export function Calendar({ selected, onSelect, defaultMonth, className }: CalendarProps) {
  return (
    <DayPicker
      mode="single"
      selected={selected}
      onSelect={onSelect}
      {...(defaultMonth ? { defaultMonth } : {})}
      className={cn("p-3", className)}
    />
  );
}
